window.SLIDES=[{"sub": "5.1", "n": 1, "N": 6, "kicker": "DEFINISI", "title": "Bulatan dan bahagiannya", "body": "<div class=\"sl-def\" style=\"--c:#FB923C\"><p><b>Bulatan</b> ialah lingkaran bagi satu titik yang bergerak sama jarak dari satu titik tetap.</p></div><ul class=\"sl-bul\" style=\"--c:#FB923C\"><li><span><b>Pusat:</b> Satu titik tetap yang berjarak sama dari semua titik pada lilitan bulatan.</span></li><li><span><b>Jejari:</b> Garis lurus dari pusat bulatan ke sebarang titik pada lilitan bulatan.</span></li><li><span><b>Lilitan:</b> Perimeter sebuah bulatan.</span></li><li><span><b>Diameter:</b> Garis lurus yang menyentuh lilitan dan melalui pusat bulatan.</span></li></ul>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan dengan pusat, jejari, diameter dan lilitan\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"#38BDF818\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"234.0\" y=\"237.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><line x1=\"250.0\" y1=\"225.0\" x2=\"388.6\" y2=\"145.0\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><text x=\"324.6\" y=\"170.4\" fill=\"#FB923C\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">jejari</text><line x1=\"99.6\" y1=\"279.7\" x2=\"400.4\" y2=\"170.3\" stroke=\"#34D399\" stroke-width=\"3.5\"/><text x=\"174.8\" y=\"280.4\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">diameter</text><text x=\"185.7\" y=\"54.3\" fill=\"#38BDF8\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">lilitan</text></svg>", "full": ""}, {"sub": "5.1", "n": 2, "N": 6, "kicker": "DEFINISI", "title": "Perentas, lengkok, sektor dan tembereng", "body": "<ul class=\"sl-bul\" style=\"--c:#FB923C\"><li><span><b>Perentas:</b> Garis lurus yang menyambung sebarang dua titik pada lilitan.</span></li><li><span><b>Lengkok:</b> Lengkok adalah sebahagian daripada lilitan.</span></li><li><span><b>Sektor:</b> Rantau yang dibatasi oleh satu lengkok dan dua jejari.</span></li><li><span><b>Tembereng:</b> Rantau yang dibatasi oleh satu lengkok dan satu perentas.</span></li></ul><div class=\"sl-note\"><b>Ingat:</b> Diameter ialah perentas yang paling panjang bagi sesuatu bulatan. Sektor dan tembereng boleh jadi minor atau major.</div>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan dengan perentas, lengkok, sektor dan tembereng\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><path d=\"M250 225 L400.4 170.3 A160 160 0 0 0 277.8 67.4 Z\" fill=\"#A78BFA44\" stroke=\"#A78BFA\" stroke-width=\"3\"/><path d=\"M99.6 279.7 A160 160 0 0 0 304.7 375.4 Z\" fill=\"#FBBF2444\" stroke=\"#FBBF24\" stroke-width=\"3\"/><line x1=\"136.9\" y1=\"111.9\" x2=\"92.4\" y2=\"197.2\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"264.0\" y=\"249.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"306.6\" y=\"163.6\" fill=\"#A78BFA\" font-family=\"Space Grotesk, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">sektor</text><text x=\"187.3\" y=\"344.1\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">tembereng</text><text x=\"165.2\" y=\"170.0\" fill=\"#FB923C\" font-family=\"Space Grotesk, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">perentas</text><path d=\"M222.2 67.4 A160 160 0 0 0 158.2 93.9\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"7\"/><text x=\"180.3\" y=\"58.5\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">lengkok</text></svg>", "full": ""}, {"sub": "5.1", "n": 3, "N": 6, "kicker": "CONTOH 1", "title": "Mengenal pasti bahagian bulatan", "body": "<p class=\"sl-p\">Dalam rajah, O ialah pusat bulatan. Kenal pasti bahagian bulatan berikut.</p><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#FB923C\"><li class=\"rv\"><span class=\"n\">1</span><span><i>a</i>, Perentas &nbsp;&nbsp; <i>b</i>, Diameter</span></li><li class=\"rv\"><span class=\"n\">2</span><span><i>c</i>, Jejari &nbsp;&nbsp; <i>d</i>, Lilitan</span></li><li class=\"rv\"><span class=\"n\">3</span><span><i>e</i>, Sektor &nbsp;&nbsp; <i>f</i>, Lengkok</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan dengan bahagian berlabel a hingga f\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><path d=\"M250 225 L372.6 327.8 A160 160 0 0 0 407.6 197.2 Z\" fill=\"#A78BFA44\" stroke=\"#A78BFA\" stroke-width=\"3\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"234.0\" y=\"237.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><line x1=\"127.4\" y1=\"122.2\" x2=\"127.4\" y2=\"327.8\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><line x1=\"222.2\" y1=\"67.4\" x2=\"277.8\" y2=\"382.6\" stroke=\"#34D399\" stroke-width=\"3.5\"/><line x1=\"250.0\" y1=\"225.0\" x2=\"330.0\" y2=\"86.4\" stroke=\"#FBBF24\" stroke-width=\"3.5\"/><path d=\"M111.4 145.0 A160 160 0 0 0 99.6 279.7\" fill=\"none\" stroke=\"#E6EDF7\" stroke-width=\"2\"/><text x=\"112.0\" y=\"231.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"middle\">a</text><text x=\"241.4\" y=\"132.2\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"middle\">b</text><text x=\"274.6\" y=\"163.3\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"middle\">c</text><text x=\"158.0\" y=\"390.3\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"middle\">d</text><text x=\"342.7\" y=\"255.8\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"middle\">e</text><text x=\"409.3\" y=\"139.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"middle\">f</text><path d=\"M404.5 183.6 A160 160 0 0 0 363.1 111.9\" fill=\"none\" stroke=\"#38BDF8\" stroke-width=\"7\"/></svg>", "full": ""}, {"sub": "5.1", "n": 4, "N": 6, "kicker": "KONSEP", "title": "Membina bulatan dan diameter", "body": "<p class=\"sl-p\">(a) Bina bulatan apabila diberi jejari 4 cm dan berpusat O. (b) Bina diameter yang melalui titik Q dalam bulatan yang berpusat di titik O.</p><ol class=\"sl-steps\" style=\"--c:#FB923C\"><li class=\"rv\"><span class=\"n\">1</span><span>(a) 1. Tandakan satu titik O. 2. Ukur jangka lukis berjarak 4 cm pada pembaris.</span></li><li class=\"rv\"><span class=\"n\">2</span><span>3. Letakkan hujung tajam jangka lukis pada titik O dan lukis sebuah bulatan berjejari 4 cm.</span></li><li class=\"rv\"><span class=\"n\">3</span><span>(b) 1. Sambungkan titik O dan Q dengan garis lurus menggunakan pembaris.</span></li><li class=\"rv\"><span class=\"n\">4</span><span>2. Lanjutkan garis itu sehingga menyentuh lilitan. Maka, garis lurus yang melalui Q dan pusat yang menyentuh lilitan ialah <b>diameter</b>.</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Pembinaan bulatan berjejari 4 cm dan diameter melalui Q\"><g class=\"rv\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/></g><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"266.0\" y=\"221.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><circle cx=\"187.6\" cy=\"189.0\" r=\"5\" fill=\"#FBBF24\"/><text x=\"173.6\" y=\"183.0\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">Q</text><g class=\"rv\"><line x1=\"250.0\" y1=\"225.0\" x2=\"410.0\" y2=\"225.0\" stroke=\"#FB923C\" stroke-width=\"3\"/><text x=\"330.0\" y=\"217.0\" fill=\"#FB923C\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">4 cm</text></g><g class=\"rv\"><line x1=\"111.4\" y1=\"145.0\" x2=\"388.6\" y2=\"305.0\" stroke=\"#34D399\" stroke-width=\"3.5\"/><text x=\"343.1\" y=\"297.0\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">diameter</text></g></svg>", "full": ""}, {"sub": "5.1", "n": 5, "N": 6, "kicker": "KONSEP", "title": "Membina perentas", "body": "<p class=\"sl-p\">(c) Bina perentas dengan panjang 4 cm dari titik P pada bulatan.</p><ol class=\"sl-steps\" style=\"--c:#FB923C\"><li class=\"rv\"><span class=\"n\">1</span><span>1. Buka jangka lukis pada pembaris dan ukur selebar 4 cm.</span></li><li class=\"rv\"><span class=\"n\">2</span><span>2. Letakkan hujung tajam jangka lukis pada titik P.</span></li><li class=\"rv\"><span class=\"n\">3</span><span>3. Lukis lengkok yang memotong lilitan dan labelkan titik A.</span></li><li class=\"rv\"><span class=\"n\">4</span><span>4. Sambungkan titik P ke titik A yang telah ditanda pada lilitan.</span></li><li class=\"rv\"><span class=\"n\">5</span><span>5. Maka, garisan PA ialah <b>perentas</b>.</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Pembinaan perentas PA sepanjang 4 cm\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"234.0\" y=\"237.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><circle cx=\"170.0\" cy=\"86.4\" r=\"5\" fill=\"#FBBF24\"/><text x=\"156.0\" y=\"78.4\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">P</text><g class=\"rv\"><circle cx=\"330.0\" cy=\"86.4\" r=\"5\" fill=\"#FBBF24\"/><text x=\"344.0\" y=\"78.4\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">A</text></g><g class=\"rv\"><line x1=\"170.0\" y1=\"86.4\" x2=\"330.0\" y2=\"86.4\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><text x=\"250.0\" y=\"53.0\" fill=\"#FB923C\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">4 cm</text></g></svg>", "full": ""}, {"sub": "5.1", "n": 6, "N": 6, "kicker": "KONSEP", "title": "Membina sektor bulatan", "body": "<p class=\"sl-p\">(d) Bina sektor bulatan bersudut 50° pada pusat bulatan yang berjejari 3 cm.</p><ol class=\"sl-steps\" style=\"--c:#FB923C\"><li class=\"rv\"><span class=\"n\">1</span><span>1. Lukis sebuah bulatan berpusat O dengan panjang jejari OA ialah 3 cm.</span></li><li class=\"rv\"><span class=\"n\">2</span><span>2. Dengan menggunakan protraktor, tandakan satu titik pada sudut 50° dari jejari OA.</span></li><li class=\"rv\"><span class=\"n\">3</span><span>3. Lukis jejari OB dengan menyambung pusat O dari titik itu dengan garis lurus. Maka, AOB ialah <b>sektor bulatan</b>.</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Pembinaan sektor AOB bersudut 50 darjah\"><g class=\"rv\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"234.0\" y=\"237.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><line x1=\"250.0\" y1=\"225.0\" x2=\"250.0\" y2=\"385.0\" stroke=\"#E6EDF7\" stroke-width=\"3\"/><text x=\"250.0\" y=\"413.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">A</text></g><g class=\"rv\"><circle cx=\"372.6\" cy=\"327.8\" r=\"5\" fill=\"#FBBF24\"/><text x=\"313.0\" y=\"280.3\" fill=\"#A78BFA\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">50°</text></g><g class=\"rv\"><path d=\"M250 225 L250.0 385.0 A160 160 0 0 0 372.6 327.8 Z\" fill=\"#A78BFA44\" stroke=\"#A78BFA\" stroke-width=\"3\"/><text x=\"388.6\" y=\"343.8\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">B</text></g></svg>", "full": ""}, {"sub": "5.2", "n": 1, "N": 6, "kicker": "KONSEP", "title": "Ciri-ciri bulatan", "body": "<ul class=\"sl-bul\" style=\"--c:#38BDF8\"><li><span>Diameter sebuah bulatan merupakan suatu paksi simetri bulatan tersebut.</span></li><li><span>Jejari yang berserenjang dengan perentas membahagi dua sama perentas itu.</span></li><li><span>Pembahagi dua sama serenjang dua perentas bertemu di pusat bulatan.</span></li><li><span>Perentas yang sama panjang menghasilkan lengkok yang sama panjang.</span></li><li><span>Dua perentas yang sama panjang adalah sama jarak dari pusat bulatan dan sebaliknya.</span></li></ul><div class=\"sl-note\"><b>Tip:</b> Diameter ialah perentas yang melalui pusat bulatan.</div>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Jejari serenjang dengan perentas MN\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"#38BDF818\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><line x1=\"90.0\" y1=\"225.0\" x2=\"410.0\" y2=\"225.0\" stroke=\"#FBBF24\" stroke-width=\"2.5\" stroke-dasharray=\"8 6\"/><line x1=\"136.9\" y1=\"111.9\" x2=\"136.9\" y2=\"338.1\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"266.0\" y=\"219.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"120.9\" y=\"107.9\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">M</text><text x=\"120.9\" y=\"360.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">N</text><line x1=\"136.9\" y1=\"225.0\" x2=\"250.0\" y2=\"225.0\" stroke=\"#E6EDF7\" stroke-width=\"2\"/><path d=\"M150.9 225.0 L150.9 211.0 L136.9 211.0\" fill=\"none\" stroke=\"#E6EDF7\" stroke-width=\"2\"/><text x=\"250.0\" y=\"430.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">Jejari yang berserenjang dengan perentas</text><text x=\"250.0\" y=\"450.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">membahagi dua sama perentas itu</text></svg>", "full": ""}, {"sub": "5.2", "n": 2, "N": 6, "kicker": "CONTOH 2", "title": "Paksi simetri dan Teorem Pythagoras", "body": "<p class=\"sl-p\">Rajah di sebelah menunjukkan sebuah bulatan dengan pusat O dan garis MN ialah perentas. (a) Namakan paksi simetri bagi rajah ini. (b) Diberi OK = 6 cm dan NK = 8 cm, hitung panjang ON. (c) Namakan sudut yang sama saiz dengan ∠ONK.</p><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#38BDF8\"><li class=\"rv\"><span class=\"n\">1</span><span>(a) AOB dan POQ</span></li><li class=\"rv\"><span class=\"n\">2</span><span>(b) ON² = 8² + 6², ON = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">64 + 36</span> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">100</span>, ON = 10. Maka, panjang ON ialah 10 cm.</span></li><li class=\"rv\"><span class=\"n\">3</span><span>(c) ∠OMK</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan berpusat O dengan perentas MN\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"#38BDF818\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><line x1=\"250.0\" y1=\"65.0\" x2=\"250.0\" y2=\"385.0\" stroke=\"#E6EDF7\" stroke-width=\"2.5\"/><line x1=\"90.0\" y1=\"225.0\" x2=\"410.0\" y2=\"225.0\" stroke=\"#E6EDF7\" stroke-width=\"2.5\"/><line x1=\"153.7\" y1=\"97.2\" x2=\"153.7\" y2=\"352.8\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><line x1=\"250.0\" y1=\"225.0\" x2=\"153.7\" y2=\"352.8\" stroke=\"#34D399\" stroke-width=\"3\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"266.0\" y=\"219.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"250.0\" y=\"55.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">A</text><text x=\"250.0\" y=\"413.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">B</text><text x=\"72.0\" y=\"231.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">P</text><text x=\"428.0\" y=\"231.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">Q</text><text x=\"139.7\" y=\"91.2\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">M</text><text x=\"139.7\" y=\"376.8\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">N</text><text x=\"135.7\" y=\"217.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">K</text><path d=\"M167.7 225.0 L167.7 211.0 L153.7 211.0\" fill=\"none\" stroke=\"#E6EDF7\" stroke-width=\"2\"/></svg>", "full": ""}, {"sub": "5.2", "n": 3, "N": 6, "kicker": "CONTOH 3", "title": "Jejari serenjang dengan perentas", "body": "<p class=\"sl-p\">Rajah di sebelah menunjukkan sebuah bulatan dengan perentas MN yang berserenjang dengan jejari OP. (a) Adakah panjang MS sama dengan panjang SN? Jelaskan. (b) Jika jejari bulatan ialah 13 cm dan OS = 5 cm, hitung panjang perentas MN.</p><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#38BDF8\"><li class=\"rv\"><span class=\"n\">1</span><span>(a) Ya, MS = SN. Jejari OP yang berserenjang dengan perentas membahagi dua sama perentas.</span></li><li class=\"rv\"><span class=\"n\">2</span><span>(b) MS = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">13² − 5²</span> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">169 − 25</span> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">144</span></span></li><li class=\"rv\"><span class=\"n\">3</span><span>MS = SN = 12. Maka, MN = 24 cm.</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan dengan perentas MN dan jejari OP\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"#38BDF818\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><line x1=\"105.0\" y1=\"292.6\" x2=\"395.0\" y2=\"292.6\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><line x1=\"250.0\" y1=\"225.0\" x2=\"250.0\" y2=\"385.0\" stroke=\"#E6EDF7\" stroke-width=\"3\"/><line x1=\"250.0\" y1=\"225.0\" x2=\"105.0\" y2=\"292.6\" stroke=\"#34D399\" stroke-width=\"2.5\" stroke-dasharray=\"8 6\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"250.0\" y=\"213.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"87.0\" y=\"304.6\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">M</text><text x=\"413.0\" y=\"304.6\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">N</text><text x=\"236.0\" y=\"284.6\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">S</text><text x=\"250.0\" y=\"413.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">P</text><path d=\"M264.0 292.6 L264.0 278.6 L250.0 278.6\" fill=\"none\" stroke=\"#E6EDF7\" stroke-width=\"2\"/><text x=\"147.5\" y=\"256.8\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">13 cm</text><text x=\"280.0\" y=\"264.8\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">5 cm</text></svg>", "full": ""}, {"sub": "5.2", "n": 4, "N": 6, "kicker": "CONTOH 4", "title": "Perentas yang sama panjang", "body": "<p class=\"sl-p\">Rajah di sebelah menunjukkan dua perentas yang sama panjang RS dan TU. POQ ialah garis lurus yang melalui pusat bulatan O. Diberi OP = 8 cm dan RS = 30 cm. (a) Hitung panjang PR. (b) Adakah lengkok minor RMS dan TNU sama panjang? Jelaskan. (c) Hitung jejari bulatan itu.</p><ol class=\"sl-steps\" style=\"--c:#38BDF8\"><li class=\"rv\"><span class=\"n\">1</span><span>(a) Jejari yang berserenjang dengan perentas, membahagi perentas itu kepada dua bahagian yang sama panjang. PR = 30 ÷ 2 = 15 cm</span></li><li class=\"rv\"><span class=\"n\">2</span><span>(b) Ya, perentas yang sama panjang menghasilkan lengkok yang sama panjang.</span></li><li class=\"rv\"><span class=\"n\">3</span><span>(c) OR = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">PR² + OP²</span> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">15² + 8²</span> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">289</span> = 17 cm</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan dengan dua perentas sama panjang RS dan TU\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"#38BDF818\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><line x1=\"108.7\" y1=\"149.9\" x2=\"391.3\" y2=\"149.9\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><line x1=\"108.7\" y1=\"300.1\" x2=\"391.3\" y2=\"300.1\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><line x1=\"250.0\" y1=\"65.0\" x2=\"250.0\" y2=\"385.0\" stroke=\"#E6EDF7\" stroke-width=\"2.5\"/><line x1=\"250.0\" y1=\"225.0\" x2=\"108.7\" y2=\"149.9\" stroke=\"#34D399\" stroke-width=\"2.5\" stroke-dasharray=\"8 6\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"266.0\" y=\"235.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"92.7\" y=\"147.9\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">R</text><text x=\"407.3\" y=\"147.9\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">S</text><text x=\"92.7\" y=\"320.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">T</text><text x=\"407.3\" y=\"320.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">U</text><text x=\"264.0\" y=\"139.9\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">P</text><text x=\"264.0\" y=\"328.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">Q</text><text x=\"250.0\" y=\"55.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">M</text><text x=\"250.0\" y=\"413.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">N</text><path d=\"M264.0 149.9 L264.0 163.9 L250.0 163.9\" fill=\"none\" stroke=\"#E6EDF7\" stroke-width=\"2\"/><path d=\"M264.0 300.1 L264.0 286.1 L250.0 286.1\" fill=\"none\" stroke=\"#E6EDF7\" stroke-width=\"2\"/></svg>", "full": ""}, {"sub": "5.2", "n": 5, "N": 6, "kicker": "KONSEP", "title": "Pusat dan jejari bulatan", "body": "<div class=\"sl-def\" style=\"--c:#38BDF8\"><p>Pembahagi dua sama serenjang bagi sebarang perentas akan sentiasa bersilang di pusat bulatan.</p></div><ol class=\"sl-steps\" style=\"--c:#38BDF8\"><li class=\"rv\"><span class=\"n\">1</span><span>Surih bentuk bulat pada sehelai kertas.</span></li><li class=\"rv\"><span class=\"n\">2</span><span>Bina dua perentas, PQ dan PR dari titik P bulatan itu.</span></li><li class=\"rv\"><span class=\"n\">3</span><span>Bina garisan pembahagi dua sama serenjang bagi perentas PQ dan PR.</span></li><li class=\"rv\"><span class=\"n\">4</span><span>Titik persilangan dua garisan pembahagi dua sama serenjang ditandakan dengan O. Lukis satu garisan dari O ke lilitan bulatan dan namakannya sebagai OT.</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Pembahagi dua sama serenjang dua perentas bertemu di pusat O\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><line x1=\"195.3\" y1=\"74.6\" x2=\"400.4\" y2=\"170.3\" stroke=\"#FB923C\" stroke-width=\"3\"/><line x1=\"195.3\" y1=\"74.6\" x2=\"99.6\" y2=\"279.7\" stroke=\"#FB923C\" stroke-width=\"3\"/><text x=\"185.3\" y=\"64.6\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">P</text><text x=\"416.4\" y=\"170.3\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">Q</text><text x=\"83.6\" y=\"295.7\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">R</text><g class=\"rv\"><line x1=\"323.2\" y1=\"68.1\" x2=\"196.4\" y2=\"340.0\" stroke=\"#FBBF24\" stroke-width=\"2.5\" stroke-dasharray=\"8 6\"/></g><g class=\"rv\"><line x1=\"201.8\" y1=\"202.5\" x2=\"-70.1\" y2=\"75.8\" stroke=\"#FBBF24\" stroke-width=\"2.5\" stroke-dasharray=\"8 6\"/></g><g class=\"rv\"><circle cx=\"250.0\" cy=\"225.0\" r=\"7\" fill=\"#34D399\"/><text x=\"268.0\" y=\"245.0\" fill=\"#34D399\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text></g></svg>", "full": ""}, {"sub": "5.2", "n": 6, "N": 6, "kicker": "CONTOH 5", "title": "Penyelesaian masalah", "body": "<p class=\"sl-p\">Seorang tukang besi diminta membina sebuah kerangka tingkap berbentuk bulatan. Tingkap berbentuk bulatan itu berdiameter 26 cm. Tiga batang besi, PR, US dan QT yang tidak sama panjang digunakan untuk menyokong tingkap tersebut. Hitung panjang PR.</p><ol class=\"sl-steps\" style=\"--c:#38BDF8\"><li class=\"rv\"><span class=\"n\">1</span><span><b>Memahami masalah:</b> Jejari = 26 ÷ 2 = 13 cm. Hitung PR.</span></li><li class=\"rv\"><span class=\"n\">2</span><span><b>Merancang strategi:</b> OT = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">OU² − UT²</span>, OQ = QT − OT, PQ = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">OP² − OQ²</span>, PR = PQ × 2</span></li><li class=\"rv\"><span class=\"n\">3</span><span><b>Melaksanakan strategi:</b> OT = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">13² − 12²</span> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">25</span> = 5 cm. OQ = 17 − 5 = 12 cm. PQ = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">13² − 12²</span> = 5 cm. PR = 5 + 5 = 10 cm</span></li><li class=\"rv\"><span class=\"n\">4</span><span><b>Membuat kesimpulan:</b> Maka, PR ialah 10 cm.</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Kerangka tingkap bulat dengan batang besi PR, US dan QT\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"#38BDF818\" stroke=\"#38BDF8\" stroke-width=\"3.5\"/><line x1=\"102.3\" y1=\"163.5\" x2=\"102.3\" y2=\"286.5\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><line x1=\"309.9\" y1=\"76.7\" x2=\"309.9\" y2=\"373.3\" stroke=\"#FB923C\" stroke-width=\"3.5\"/><line x1=\"102.3\" y1=\"225.0\" x2=\"309.9\" y2=\"225.0\" stroke=\"#FBBF24\" stroke-width=\"3.5\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"250.0\" y=\"215.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"90.3\" y=\"155.5\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">P</text><text x=\"90.3\" y=\"310.5\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">R</text><text x=\"86.3\" y=\"219.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">Q</text><text x=\"321.9\" y=\"68.7\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">U</text><text x=\"321.9\" y=\"397.3\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">S</text><text x=\"325.9\" y=\"219.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">T</text><text x=\"250.0\" y=\"450.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">Diameter = 26 cm, QT = 17 cm, US = 24 cm</text></svg>", "full": ""}, {"sub": "5.3", "n": 1, "N": 17, "kicker": "KONSEP", "title": "Hubungan lilitan bulatan dengan diameter", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p><b>Lilitan bulatan</b> ialah ukuran sekeliling bagi satu bulatan.</p></div><p class=\"sl-p\">Nilai nisbah lilitan kepada diameter, iaitu π suatu bulatan ialah 3.142 atau <span class=\"fr\"><span>22</span><span>7</span></span>. &nbsp; <span class=\"fr\"><span>Lilitan</span><span>Diameter</span></span> = π</p><div style=\"display: flex; flex-direction: column; gap: 12px\"><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #34D399\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #34D399\">LILITAN</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">lilitan = π × diameter = π<i>d</i></p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #38BDF8\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #38BDF8\">LILITAN</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\">lilitan = π × 2 × jejari = 2π<i>j</i></p></div></div><div class=\"sl-note\"><b>Ingat:</b> Diameter = 2 × Jejari. π dibaca sebagai \"pai\".</div>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan dengan diameter d\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"#34D39918\" stroke=\"#34D399\" stroke-width=\"3.5\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><line x1=\"90.0\" y1=\"225.0\" x2=\"410.0\" y2=\"225.0\" stroke=\"#FBBF24\" stroke-width=\"3.5\"/><text x=\"250.0\" y=\"213.0\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">d</text><text x=\"250.0\" y=\"430.0\" fill=\"#34D399\" font-family=\"Inter, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">Lilitan ÷ Diameter = π</text></svg>", "full": ""}, {"sub": "5.3", "n": 2, "N": 17, "kicker": "KONSEP", "title": "Rumus luas bulatan", "body": "<p class=\"sl-p\">Semakin banyak sektor bulatan itu dibahagikan, semakin jelas bentuk segi empat tepat yang dihasilkan. Didapati bahawa luas bulatan = luas segi empat tepat</p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span>= tapak × tinggi</span></li><li class=\"rv\"><span class=\"n\">2</span><span>= <span class=\"fr\"><span>1</span><span>2</span></span> × lilitan bulatan × tinggi</span></li><li class=\"rv\"><span class=\"n\">3</span><span>= <span class=\"fr\"><span>1</span><span>2</span></span> × 2π<i>j</i> × <i>j</i> = π<i>j</i>²</span></li><li class=\"rv\"><span class=\"n\">4</span><span><b>Maka, luas bulatan = π<i>j</i>²</b></span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Sektor bulatan disusun menjadi segi empat tepat\"><path d=\"M92 300 L70 120 Q92 108 115 120 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><path d=\"M137 120 L115 300 Q137 312 160 300 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><path d=\"M182 300 L160 120 Q182 108 205 120 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><path d=\"M227 120 L205 300 Q227 312 250 300 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><path d=\"M272 300 L250 120 Q272 108 295 120 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><path d=\"M317 120 L295 300 Q317 312 340 300 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><path d=\"M362 300 L340 120 Q362 108 385 120 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><path d=\"M407 120 L385 300 Q407 312 430 300 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"2\"/><text x=\"250.0\" y=\"345.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">tapak = ½ × lilitan = π<tspan font-style=\"italic\">j</tspan></text><text x=\"40.0\" y=\"215.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"20\" font-weight=\"700\" text-anchor=\"middle\">j</text><text x=\"250.0\" y=\"420.0\" fill=\"#FBBF24\" font-family=\"Inter, sans-serif\" font-size=\"24\" font-weight=\"700\" text-anchor=\"middle\">luas bulatan = π<tspan font-style=\"italic\">j</tspan>²</text></svg>", "full": ""}, {"sub": "5.3", "n": 3, "N": 17, "kicker": "CONTOH 6", "title": "Menentukan lilitan bulatan", "body": "<p class=\"sl-p\">Hitung lilitan sebuah bulatan jika (a) diameter, <i>d</i> = 21 cm. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>) (b) jejari, <i>j</i> = 12.5 cm. (Guna π = 3.142)</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><b style=\"color:#34D399\">(a)</b> <div class=\"rv\">Lilitan = π<i>d</i></div><div class=\"rv\">= <span class=\"fr\"><span>22</span><span>7</span></span> × 21</div><div class=\"rv\">= 66 cm</div></div><div><b style=\"color:#34D399\">(b)</b> <div class=\"rv\">Lilitan = 2π<i>j</i></div><div class=\"rv\">= 2 × 3.142 × 12.5</div><div class=\"rv\">= 78.55 cm</div></div></div>", "full": ""}, {"sub": "5.3", "n": 4, "N": 17, "kicker": "CONTOH 7", "title": "Menentukan diameter dan jejari", "body": "<p class=\"sl-p\">(a) Diberi lilitan sebuah bulatan ialah 132 cm. Hitung diameter, dalam cm, bulatan tersebut. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>)</p><p class=\"sl-p\">(b) Diberi lilitan sebuah bulatan ialah 40.5 cm. Hitung jejari bulatan, dalam cm dan bundarkan kepada dua tempat perpuluhan. (Guna π = 3.142)</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><b style=\"color:#34D399\">(a)</b> <div class=\"rv\">Lilitan = π<i>d</i></div><div class=\"rv\">132 = <span class=\"fr\"><span>22</span><span>7</span></span> × <i>d</i></div><div class=\"rv\"><i>d</i> = 132 × <span class=\"fr\"><span>7</span><span>22</span></span></div><div class=\"rv\"><i>d</i> = 42 cm</div></div><div><b style=\"color:#34D399\">(b)</b> <div class=\"rv\">Lilitan = 2π<i>j</i></div><div class=\"rv\">2 × 3.142 × <i>j</i> = 40.5</div><div class=\"rv\"><i>j</i> = <span class=\"fr\"><span>40.5</span><span>6.284</span></span></div><div class=\"rv\"><i>j</i> = 6.44 cm</div></div></div>", "full": ""}, {"sub": "5.3", "n": 5, "N": 17, "kicker": "CONTOH 8", "title": "Menentukan luas bulatan", "body": "<p class=\"sl-p\">Hitung luas bulatan yang mempunyai (a) diameter 12 cm. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>) (b) jejari 14 cm. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>)</p><div class=\"sl-note\"><b>Ingat:</b> jejari, <i>j</i> = <span class=\"fr\"><span>diameter</span><span>2</span></span>, diameter, <i>d</i> = 2<i>j</i></div>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><b style=\"color:#34D399\">(a)</b> <div class=\"rv\">Luas = π<i>j</i>²</div><div class=\"rv\">= <span class=\"fr\"><span>22</span><span>7</span></span> × (<span class=\"fr\"><span>12</span><span>2</span></span>)²</div><div class=\"rv\">= 113.14 cm²</div></div><div><b style=\"color:#34D399\">(b)</b> <div class=\"rv\">Luas = π<i>j</i>²</div><div class=\"rv\">= <span class=\"fr\"><span>22</span><span>7</span></span> × 14²</div><div class=\"rv\">= 616 cm²</div></div></div>", "full": ""}, {"sub": "5.3", "n": 6, "N": 17, "kicker": "CONTOH 9", "title": "Jejari dan diameter daripada luas", "body": "<p class=\"sl-p\">Diberi luas bulatan ialah 154 cm². Hitung jejari dan diameter. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>)</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><div class=\"rv\">Luas = π<i>j</i>²</div><div class=\"rv\"><span class=\"fr\"><span>22</span><span>7</span></span> × <i>j</i>² = 154</div><div class=\"rv\"><i>j</i>² = 154 × <span class=\"fr\"><span>7</span><span>22</span></span></div><div class=\"rv\"><i>j</i>² = 49</div><div class=\"rv\"><i>j</i> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">49</span></div><div class=\"rv\"><i>j</i> = 7 cm</div><div class=\"rv\">Diameter = 2 × 7 = 14 cm</div></div></div>", "full": ""}, {"sub": "5.3", "n": 7, "N": 17, "kicker": "CONTOH 10", "title": "Luas daripada lilitan", "body": "<p class=\"sl-p\">Diberi lilitan bulatan ialah 88 cm. Hitung luas bulatan. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>)</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><div class=\"rv\">Lilitan = 88 cm</div><div class=\"rv\">2π<i>j</i> = 88</div><div class=\"rv\">2 × <span class=\"fr\"><span>22</span><span>7</span></span> × <i>j</i> = 88</div><div class=\"rv\"><i>j</i> = 88 × <span class=\"fr\"><span>7</span><span>44</span></span></div><div class=\"rv\"><i>j</i> = 14 cm</div><div class=\"rv\">Luas = π<i>j</i>² = <span class=\"fr\"><span>22</span><span>7</span></span> × 14²</div><div class=\"rv\">= 616 cm²</div></div></div>", "full": ""}, {"sub": "5.3", "n": 8, "N": 17, "kicker": "CONTOH 11", "title": "Lilitan daripada luas", "body": "<p class=\"sl-p\">Diberi luas bulatan ialah 38.5 cm². Hitung lilitan bulatan. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>)</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><div class=\"rv\">Luas = π<i>j</i>²</div><div class=\"rv\"><span class=\"fr\"><span>22</span><span>7</span></span> × <i>j</i>² = 38.5</div><div class=\"rv\"><i>j</i>² = 38.5 × <span class=\"fr\"><span>7</span><span>22</span></span></div><div class=\"rv\"><i>j</i>² = 12.25</div><div class=\"rv\"><i>j</i> = √<span style=\"border-top:2px solid currentColor;padding:0 3px\">12.25</span> = 3.5 cm</div><div class=\"rv\">Lilitan = 2π<i>j</i> = 2 × <span class=\"fr\"><span>22</span><span>7</span></span> × 3.5</div><div class=\"rv\">= 22 cm</div></div></div>", "full": ""}, {"sub": "5.3", "n": 9, "N": 17, "kicker": "KONSEP", "title": "Panjang lengkok suatu bulatan", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p>Lengkok bulatan merupakan sebahagian daripada lilitan bulatan. Lengkok bulatan berkadaran dengan sudut pada pusat bulatan.</p></div><div style=\"display: flex; flex-direction: column; gap: 12px\"><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #34D399\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #34D399\">PANJANG LENGKOK</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\"><span class=\"fr\"><span>Panjang lengkok</span><span>Lilitan bulatan</span></span> = <span class=\"fr\"><span>Sudut pada pusat</span><span>360°</span></span></p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #FBBF24\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #FBBF24\">MAKA</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\"><span class=\"fr\"><span>Panjang lengkok</span><span>2π<i>j</i></span></span> = <span class=\"fr\"><span>θ</span><span>360°</span></span></p></div></div>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Sektor dengan sudut θ dan lengkok AB\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"3.5\"/><path d=\"M250 225 L352.8 102.4 A160 160 0 0 0 195.3 74.6 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"3\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"250.0\" y=\"251.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"265.3\" y=\"144.3\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">θ</text><path d=\"M352.8 102.4 A160 160 0 0 0 195.3 74.6\" fill=\"none\" stroke=\"#FBBF24\" stroke-width=\"7\"/><text x=\"176.1\" y=\"72.7\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">A</text><text x=\"371.1\" y=\"102.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">B</text><text x=\"250.0\" y=\"425.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">Simbol θ dibaca \"theta\", ialah huruf Yunani</text><text x=\"250.0\" y=\"447.0\" fill=\"#94A3B8\" font-family=\"Inter, sans-serif\" font-size=\"15\" font-weight=\"700\" text-anchor=\"middle\">yang digunakan untuk mewakili sudut.</text></svg>", "full": ""}, {"sub": "5.3", "n": 10, "N": 17, "kicker": "CONTOH 12", "title": "Panjang lengkok minor", "body": "<p class=\"sl-p\">Rajah di sebelah menunjukkan sebuah bulatan dengan jejari 21 cm dan berpusat di O. Hitung panjang lengkok minor PQ yang mencangkum 80° pada pusat. Tulis jawapan dalam dua tempat perpuluhan.</p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span><span class=\"fr\"><span>Panjang lengkok</span><span>2π<i>j</i></span></span> = <span class=\"fr\"><span>θ</span><span>360°</span></span></span></li><li class=\"rv\"><span class=\"n\">2</span><span>Panjang lengkok = <span class=\"fr\"><span>θ</span><span>360°</span></span> × 2π<i>j</i></span></li><li class=\"rv\"><span class=\"n\">3</span><span>Panjang lengkok = <span class=\"fr\"><span>80°</span><span>360°</span></span> × 2 × <span class=\"fr\"><span>22</span><span>7</span></span> × 21</span></li><li class=\"rv\"><span class=\"n\">4</span><span>= 29.33 cm</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan berjejari 21 cm dengan lengkok minor PQ\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"3.5\"/><path d=\"M250 225 L352.8 102.4 A160 160 0 0 0 147.2 102.4 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"3\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"250.0\" y=\"251.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"250.0\" y=\"159.0\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">80°</text><path d=\"M352.8 102.4 A160 160 0 0 0 147.2 102.4\" fill=\"none\" stroke=\"#FBBF24\" stroke-width=\"7\"/><text x=\"128.9\" y=\"102.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">P</text><text x=\"371.1\" y=\"102.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">Q</text><line x1=\"250.0\" y1=\"225.0\" x2=\"330.0\" y2=\"363.6\" stroke=\"#E6EDF7\" stroke-width=\"2.5\"/><text x=\"332.0\" y=\"314.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">21 cm</text></svg>", "full": ""}, {"sub": "5.3", "n": 11, "N": 17, "kicker": "CONTOH 13", "title": "Panjang lengkok major", "body": "<p class=\"sl-p\">Rajah di sebelah menunjukkan sebuah bulatan dengan jejari 14 cm dan berpusat di O. ∠ROS ialah 90°. Hitung panjang lengkok major RS.</p><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span>Sudut pada pusat = 360° − 90° = 270°</span></li><li class=\"rv\"><span class=\"n\">2</span><span><span class=\"fr\"><span>Panjang lengkok</span><span>2π<i>j</i></span></span> = <span class=\"fr\"><span>θ</span><span>360°</span></span></span></li><li class=\"rv\"><span class=\"n\">3</span><span>Panjang lengkok = <span class=\"fr\"><span>270°</span><span>360°</span></span> × 2 × <span class=\"fr\"><span>22</span><span>7</span></span> × 14</span></li><li class=\"rv\"><span class=\"n\">4</span><span>= 66 cm</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan dengan lengkok major RS\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"3.5\"/><path d=\"M250 225 L136.9 338.1 A160 160 0 0 0 363.1 338.1 Z\" fill=\"#38BDF844\" stroke=\"#38BDF8\" stroke-width=\"3\"/><path d=\"M363.1 338.1 A160 160 0 1 0 136.9 338.1\" fill=\"none\" stroke=\"#FBBF24\" stroke-width=\"7\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"250.0\" y=\"213.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"250.0\" y=\"303.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">90°</text><text x=\"120.9\" y=\"358.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">R</text><text x=\"379.1\" y=\"358.1\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">S</text></svg>", "full": ""}, {"sub": "5.3", "n": 12, "N": 17, "kicker": "CONTOH 14", "title": "Jejari daripada panjang lengkok", "body": "<p class=\"sl-p\">Diberi panjang lengkok suatu bulatan ialah 22 cm dan sudut pada pusat bulatan ialah 60°. Hitung panjang, dalam cm, jejari bulatan itu.</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><div class=\"rv\"><span class=\"fr\"><span>θ</span><span>360°</span></span> = <span class=\"fr\"><span>Panjang lengkok</span><span>2π<i>j</i></span></span></div><div class=\"rv\">2π<i>j</i> = Panjang lengkok × <span class=\"fr\"><span>360°</span><span>θ</span></span></div><div class=\"rv\">2 × <span class=\"fr\"><span>22</span><span>7</span></span> × <i>j</i> = 22 × <span class=\"fr\"><span>360°</span><span>60°</span></span></div><div class=\"rv\"><i>j</i> = 22 × 6 × <span class=\"fr\"><span>7</span><span>22</span></span> × <span class=\"fr\"><span>1</span><span>2</span></span></div><div class=\"rv\"><i>j</i> = 21 cm</div></div></div>", "full": ""}, {"sub": "5.3", "n": 13, "N": 17, "kicker": "KONSEP", "title": "Luas sektor bulatan", "body": "<div class=\"sl-def\" style=\"--c:#34D399\"><p>Luas sektor bulatan merupakan rantau yang dibatasi oleh satu lengkok dan dua jejari. Luas sektor bulatan adalah berkadaran dengan luas bulatan.</p></div><div style=\"display: flex; flex-direction: column; gap: 12px\"><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #34D399\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #34D399\">LUAS SEKTOR</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\"><span class=\"fr\"><span>Luas sektor bulatan</span><span>Luas bulatan</span></span> = <span class=\"fr\"><span>Sudut pada pusat</span><span>360°</span></span></p></div><div style=\"padding: 14px 20px; border-radius: 18px; background: #131C2E; border: 2px solid #FBBF24\"><p style=\"margin: 0 0 4px; font-size: 16px; font-weight: 800; letter-spacing: 0.08em; color: #FBBF24\">MAKA</p><p style=\"margin: 0; font-size: 26px; font-weight: 700\"><span class=\"fr\"><span>Luas sektor AOB</span><span>π<i>j</i>²</span></span> = <span class=\"fr\"><span>θ</span><span>360°</span></span></p></div></div>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Sektor AOB dengan sudut θ\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"3.5\"/><path d=\"M250 225 L388.6 145.0 A160 160 0 0 0 222.2 67.4 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"3\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"250.0\" y=\"251.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"287.2\" y=\"151.2\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"22\" font-weight=\"700\" text-anchor=\"middle\">θ</text><text x=\"202.7\" y=\"64.5\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">A</text><text x=\"405.3\" y=\"145.9\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">B</text></svg>", "full": ""}, {"sub": "5.3", "n": 14, "N": 17, "kicker": "CONTOH 15", "title": "Luas sektor minor", "body": "<p class=\"sl-p\">Rajah di sebelah menunjukkan sebuah bulatan dengan pusat O dan jejari 14 mm. Hitung luas sektor minor MON.</p><p class=\"sl-p\"><b>Penyelesaian:</b></p><ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span><span class=\"fr\"><span>Luas sektor</span><span>π<i>j</i>²</span></span> = <span class=\"fr\"><span>θ</span><span>360°</span></span></span></li><li class=\"rv\"><span class=\"n\">2</span><span>Luas sektor MON = <span class=\"fr\"><span>135°</span><span>360°</span></span> × <span class=\"fr\"><span>22</span><span>7</span></span> × 14²</span></li><li class=\"rv\"><span class=\"n\">3</span><span>= 231 mm²</span></li></ol>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Bulatan berjejari 14 mm dengan sektor minor MON\"><circle cx=\"250\" cy=\"225\" r=\"160\" fill=\"none\" stroke=\"#34D399\" stroke-width=\"3.5\"/><path d=\"M250 225 L195.3 74.6 A160 160 0 0 0 182.4 370.0 Z\" fill=\"#34D39944\" stroke=\"#34D399\" stroke-width=\"3\"/><circle cx=\"250.0\" cy=\"225.0\" r=\"5\" fill=\"#E6EDF7\"/><text x=\"266.0\" y=\"235.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">O</text><text x=\"170.0\" y=\"228.2\" fill=\"#FBBF24\" font-family=\"Space Grotesk, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">135°</text><text x=\"176.1\" y=\"72.7\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">M</text><text x=\"168.4\" y=\"392.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"19\" font-weight=\"700\" text-anchor=\"middle\">N</text><line x1=\"250.0\" y1=\"225.0\" x2=\"410.0\" y2=\"225.0\" stroke=\"#E6EDF7\" stroke-width=\"2.5\"/><text x=\"338.0\" y=\"217.0\" fill=\"#E6EDF7\" font-family=\"Space Grotesk, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">14 mm</text></svg>", "full": ""}, {"sub": "5.3", "n": 15, "N": 17, "kicker": "CONTOH 16", "title": "Sudut daripada luas sektor", "body": "<p class=\"sl-p\">Diberi luas sektor QOP ialah 77 cm² dan jejari 14 cm. Hitung nilai θ.</p>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><div class=\"rv\"><span class=\"fr\"><span>Luas sektor</span><span>π<i>j</i>²</span></span> = <span class=\"fr\"><span>θ</span><span>360°</span></span></div><div class=\"rv\"><span class=\"fr\"><span>θ</span><span>360°</span></span> = <span class=\"fr\"><span>77</span><span><span class=\"fr\"><span>22</span><span>7</span></span> × 14²</span></span></div><div class=\"rv\">θ = <span class=\"fr\"><span>77</span><span><span class=\"fr\"><span>22</span><span>7</span></span> × 14 × 14</span></span> × 360°</div><div class=\"rv\">θ = 45°</div></div></div>", "full": ""}, {"sub": "5.3", "n": 16, "N": 17, "kicker": "CONTOH 17", "title": "Penyelesaian masalah", "body": "<p class=\"sl-p\">Sebuah taman rekreasi berbentuk segi empat tepat dengan panjangnya 70 m dan lebarnya 50 m. Setiap penjuru taman yang berbentuk sukuan bulatan berjejari 7 m akan ditanam dengan pokok bunga dan di tengah-tengah taman akan dibina sebuah kolam ikan yang berbentuk bulat dengan diameter 28 m. Kawasan yang lain akan ditanam dengan rumput karpet. Hitung luas kawasan yang ditanam dengan rumput karpet. (Guna π = <span class=\"fr\"><span>22</span><span>7</span></span>)</p>", "fig": "<svg class=\"sl-svg\" viewBox=\"0 0 500 470\" role=\"img\" aria-label=\"Taman segi empat tepat dengan empat sukuan bulatan dan kolam\"><rect x=\"60\" y=\"80\" width=\"380\" height=\"270\" fill=\"#34D39922\" stroke=\"#34D399\" stroke-width=\"3\"/><path d=\"M60 80 L60.0 135.0 A55 55 0 0 0 115.0 80.0 Z\" fill=\"#F472B655\" stroke=\"#F472B6\" stroke-width=\"2.5\"/><path d=\"M440 80 L385.0 80.0 A55 55 0 0 0 440.0 135.0 Z\" fill=\"#F472B655\" stroke=\"#F472B6\" stroke-width=\"2.5\"/><path d=\"M440 350 L440.0 295.0 A55 55 0 0 0 385.0 350.0 Z\" fill=\"#F472B655\" stroke=\"#F472B6\" stroke-width=\"2.5\"/><path d=\"M60 350 L115.0 350.0 A55 55 0 0 0 60.0 295.0 Z\" fill=\"#F472B655\" stroke=\"#F472B6\" stroke-width=\"2.5\"/><circle cx=\"250\" cy=\"215\" r=\"75\" fill=\"#38BDF844\" stroke=\"#38BDF8\" stroke-width=\"2.5\"/><text x=\"250.0\" y=\"385.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">70 m</text><text x=\"30.0\" y=\"220.0\" fill=\"#E6EDF7\" font-family=\"Inter, sans-serif\" font-size=\"18\" font-weight=\"700\" text-anchor=\"middle\">50 m</text><text x=\"250.0\" y=\"222.0\" fill=\"#38BDF8\" font-family=\"Inter, sans-serif\" font-size=\"16\" font-weight=\"700\" text-anchor=\"middle\">kolam</text></svg>", "full": ""}, {"sub": "5.3", "n": 17, "N": 17, "kicker": "CONTOH 17", "title": "Penyelesaian masalah (sambungan)", "body": "<ol class=\"sl-steps\" style=\"--c:#34D399\"><li class=\"rv\"><span class=\"n\">1</span><span><b>Memahami masalah:</b> Jejari sukuan bulatan = 7 m. Taman berbentuk segi empat tepat, panjang = 70 m, lebar = 50 m. Diameter kolam ikan = 28 m. Hitung luas kawasan yang ditanam dengan rumput karpet.</span></li><li class=\"rv\"><span class=\"n\">2</span><span><b>Merancang strategi:</b> Luas taman rekreasi = panjang × lebar. Luas tanaman bunga = 4 × <span class=\"fr\"><span>1</span><span>4</span></span> × π<i>j</i>². Luas kolam ikan = π<i>j</i>². Kawasan rumput karpet = luas taman − luas tanaman bunga − luas kolam ikan</span></li><li class=\"rv\"><span class=\"n\">3</span><span><b>Melaksanakan strategi:</b> Lihat pengiraan di sebelah.</span></li><li class=\"rv\"><span class=\"n\">4</span><span><b>Membuat kesimpulan:</b> Maka, kawasan yang ditanam dengan rumput karpet ialah 2 730 m².</span></li></ol>", "fig": "<div style=\"width:100%;align-self:flex-start;background:#131C2E;border:1px solid #22304A;border-radius:22px;padding:18px 22px;display:flex;flex-direction:column;gap:12px;font-size:20px;line-height:1.5\"><div><b style=\"color:#34D399\">(i)</b> <div class=\"rv\">Luas taman rekreasi = 70 × 50 = 3 500 m²</div></div><div><b style=\"color:#34D399\">(ii)</b> <div class=\"rv\">Luas tanaman bunga = 4 × <span class=\"fr\"><span>1</span><span>4</span></span> × <span class=\"fr\"><span>22</span><span>7</span></span> × 7²</div><div class=\"rv\">= 154 m²</div></div><div><b style=\"color:#34D399\">(iii)</b> <div class=\"rv\">Luas kolam ikan = <span class=\"fr\"><span>22</span><span>7</span></span> × 14²</div><div class=\"rv\">= 616 m²</div></div><div><div class=\"rv\">3 500 m² − 154 m² − 616 m² = 2 730 m²</div></div></div>", "full": ""}];
